CREATE TABLE IF NOT EXISTS user (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, userAccount VARCHAR(256) NOT NULL UNIQUE, userPassword VARCHAR(512) NOT NULL, userName VARCHAR(256), userAvatar VARCHAR(1024), userProfile VARCHAR(512), userRole VARCHAR(256) NOT NULL DEFAULT 'user', editTime DATETIME DEFAULT CURRENT_TIMESTAMP, createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updateTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, isDelete TINYINT NOT NULL DEFAULT 0
) COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS app (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, appName VARCHAR(256), cover VARCHAR(512), initPrompt TEXT NOT NULL, codeGenType VARCHAR(64) NOT NULL, deployKey VARCHAR(64) UNIQUE, deployedTime DATETIME, priority INT NOT NULL DEFAULT 0, userId BIGINT UNSIGNED NOT NULL, editTime DATETIME DEFAULT CURRENT_TIMESTAMP, createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updateTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, isDelete TINYINT NOT NULL DEFAULT 0, INDEX idx_userId(userId)
) COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS chat_history (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, message MEDIUMTEXT NOT NULL, messageType VARCHAR(32) NOT NULL, appId BIGINT UNSIGNED NOT NULL, userId BIGINT UNSIGNED NOT NULL, createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updateTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, isDelete TINYINT NOT NULL DEFAULT 0, INDEX idx_appId_createTime(appId,createTime,id)
) COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ts_session(tokenHash VARCHAR(64) PRIMARY KEY, userId BIGINT UNSIGNED NOT NULL, expiresAt DATETIME NOT NULL, INDEX idx_expiry(expiresAt));
CREATE TABLE IF NOT EXISTS ts_message(id VARCHAR(64) PRIMARY KEY, appId BIGINT UNSIGNED NOT NULL, sequence BIGINT UNSIGNED AUTO_INCREMENT UNIQUE, body JSON NOT NULL, createTime DATETIME NOT NULL, INDEX idx_app_sequence(appId,sequence));
CREATE TABLE IF NOT EXISTS ts_generation(id VARCHAR(36) PRIMARY KEY, appId BIGINT UNSIGNED NOT NULL, userId BIGINT UNSIGNED NOT NULL, status VARCHAR(32) NOT NULL, error TEXT, createTime DATETIME NOT NULL, updateTime DATETIME NOT NULL, INDEX idx_generation_app(appId,createTime));
CREATE TABLE IF NOT EXISTS ts_generation_lease(appId BIGINT UNSIGNED PRIMARY KEY, generationId VARCHAR(36) NOT NULL, expiresAt DATETIME NOT NULL);
